scripts.script:
const lvl = Math.max(1, move.computedLevel || 1);
const extraLoss = 5 + (lvl - 1) * 5;
const confirm = await foundry.applications.api.DialogV2.confirm({
    window: { title: "洪波涌起" },
    content: `<p>是否额外消耗 5 点内力，使敌人再流失 <b>${extraLoss}</b> 点气血？</p>`,
    yes: { label: "消耗并增强", icon: "fas fa-check" },
    no: { label: "仅基础效果", icon: "fas fa-times" }
});

if (confirm) {
    const currentMp = actor.system.resources.mp.value;
    if (currentMp < 5) {
        ui.notifications.warn("内力不足，无法增强！");
    } else {
        await actor.update({"system.resources.mp.value": currentMp - 5});
        args.flags.damageResult.damage += extraLoss;
        args.flags.damageResult.breakdown += `\n+ 额外内力增强: ${extraLoss}`;
        ui.notifications.info("已消耗 5 内力增强洪波涌起");
    }
}

if (args.isHit) {
    const dist = canvas.grid.measureDistance(actor.token.object.center, args.target.token.object.center);
    if (dist <= 1.5) {
        ui.notifications.info(`${args.target.name} 位于1米内，请手动 [击飞]`);
    }
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    ui.notifications.info(`${args.target.name} 无架招，请手动 [击飞 1 米]`);
}

const targetCount = args.flags.damageResult.targets?.length || game.user.targets.size || 0;
if (targetCount > 0) {
    const bonus = targetCount * 10;
    args.flags.damageResult.damage += bonus;
    args.flags.damageResult.breakdown += `\n+ 人数增伤 (${targetCount}人): ${bonus}`;
}

const eff = thisItem.effects.getName("蓄劲").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, eff);

if (args.isCrit) {
    const eff = thisItem.effects.getName("乏力").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(args.target, eff);
    ui.notifications.info(`${args.target.name} 被施加 [乏力]`);
}

if (!Macros.checkStance(actor, args)) return;

// 扫描场景所有 Actor
let totalFali = 0;
canvas.tokens.placeables.forEach(t => {
    if (t.actor) {
        const fali = t.actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "fali");
        if (fali) {
            totalFali += (fali.getFlag("xjzl-system", "stacks") || 1);
        }
    }
});

if (totalFali > 0) {
    // 获取当前架招等级
    const stanceId = actor.system.martial.stance;
    const moveData = thisItem.system.moves.find(m => m.id === stanceId);
    const lvl = Math.max(1, moveData?.computedLevel || 1);
    const huti = totalFali * (5 + (lvl - 1) * 5);
    await actor.applyHealing({ healer: actor, amount: huti, type: "huti", showScrolling: true});
    ui.notifications.info(`感应到战场 ${totalFali} 层乏力，获得 ${huti} 护体`);
}

const eff = thisItem.effects.getName("乏力").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(args.target, eff);

const maxMp = actor.system.resources.mp.max;
const cost = Math.floor(maxMp / 2);
const currentMp = actor.system.resources.mp.value;
if (currentMp < cost) {
    ui.notifications.warn(`内力不足半管 (需 ${cost})`);
    args.flags.abort = true;
    return;
}
await actor.update({"system.resources.mp.value": currentMp - cost});
ui.notifications.info(`怒涛霜卷消耗 ${cost} 点内力`);

const fali = args.target.effects.find(e => e.getFlag("xjzl-system", "slug") === "fali");
if (fali) {
    const stacks = fali.getFlag("xjzl-system", "stacks") || 1;
    const lvl = Math.max(1, move.computedLevel || 1);
    const drain = stacks * (10 + (lvl - 1) * 5);
    await fali.delete();
    await args.target.applyHealing({ healer: actor, amount: -drain, type: "hp", showScrolling: true});
    await args.target.applyHealing({ healer: actor, amount: -drain, type: "mp", showScrolling: true});
    await actor.applyHealing({ healer: actor, amount: drain, type: "hp", showScrolling: true});
    await actor.applyHealing({ healer: actor, amount: drain, type: "mp", showScrolling: true});
    ui.notifications.info(`引爆 ${stacks} 层乏力，吸取 ${drain}`);
    if (stacks >= 3) {
        await game.xjzl.api.effects.addEffect(args.target, { id: "blind", duration: { rounds: 3 } });
        ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #3498db; background: rgba(52, 152, 219, 0.1);"><b><i class="fas fa-water"></i> 海浪灼目</b><br>${args.target.name} 陷入目盲 3 回合！</div></div>` });
    }
}

const hasSky = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_sky");
if (hasSky) {
    await hasSky.delete();
    const eff = thisItem.effects.getName("重溟式").toObject();
    await game.xjzl.api.effects.addEffect(actor, eff);
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #1abc9c; background: rgba(39, 174, 156, 0.1);"><b><i class="fas fa-water"></i> 剑势切换</b><br>转为 <b>[重溟式]</b>。下一次招式将附带额外特效！<br><span style="color:#e74c3c; font-size:0.9em;">【注意】出招时请在弹窗手动将伤害类型选为<b>内功</b>。</span></div></div>` });
    await game.xjzl.api.effects.addEffect(actor, thisItem.effects.getName("穹溟_已切换").toObject());
} else {
    const hasOcean = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_ocean");
    if (hasOcean) await hasOcean.delete();
    const eff = thisItem.effects.getName("穹苍式").toObject();
    await game.xjzl.api.effects.addEffect(actor, eff);
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #3498db; background: rgba(52, 152, 219, 0.1);"><b><i class="fas fa-cloud"></i> 剑势切换</b><br>转为 <b>[穹苍式]</b>。下一次招式将附带额外特效！<br><span style="color:#e74c3c; font-size:0.9em;">【注意】出招时请在弹窗手动将伤害类型选为<b>外功</b>。</span></div></div>` });
    await game.xjzl.api.effects.addEffect(actor, thisItem.effects.getName("穹溟_已切换").toObject());
}

const hasSky = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_sky");
const hasOcean = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_ocean");
if (!hasSky && !hasOcean) {
    const eff = thisItem.effects.getName("穹苍式").toObject();
    await game.xjzl.api.effects.addEffect(actor, eff);
    actor.showFloatyText("拔剑起势：穹苍", { fill: "#3498db" });
}

if (!Macros.checkStance(actor, args)) return;
const hasSky = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_sky");
const lvl = Math.max(1, args.move.computedLevel || 1);

if (hasSky) {
    const eff = thisItem.effects.getName("穹苍_待流失").toObject();
    eff.flags["xjzl-system"].maxStacks = 10;
    eff.flags["xjzl-system"].stacks = lvl;
    await game.xjzl.api.effects.addEffect(actor, eff);
    actor.showFloatyText("格挡: 充能流失", { fill: "#e74c3c" });
} else {
    const eff = thisItem.effects.getName("重溟_待回复").toObject();
    eff.flags["xjzl-system"].maxStacks = 10;
    eff.flags["xjzl-system"].stacks = lvl;
    await game.xjzl.api.effects.addEffect(actor, eff);
    actor.showFloatyText("格挡: 充能回复", { fill: "#2ecc71" });
}

const hasOcean = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_ocean");
if (hasOcean) {
    args.costConfig.mp += 20;
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #3498db; background: rgba(52, 152, 219, 0.1);"><b><i class="fas fa-tint"></i> 重溟之渊</b><br>已额外扣除 20 点内力。本次攻击距离视作 <b>+5</b> 米！</div></div>` });
}

args.config.ignoreBlock = true;
const hasOcean = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_ocean");
args.config.type = hasOcean ? "neigong" : "waigong";

if (!args.isHit) return;
const hasSky = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_sky");

// --- 本招式自带特效 ---
if (hasSky) {
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: { title: "扶摇万里 - 击退判定" },
        content: `<p>将 <b>${args.target.name}</b> 击退 5 米！</p><p>过程中是否撞击到其他敌方或障碍物？</p>`,
        yes: { label: "是 (流失与倒地)", icon: "fas fa-car-crash" },
        no: { label: "否 (仅击退)", icon: "fas fa-arrow-right" }
    });
    if (confirm) {
        await args.target.applyHealing({ healer: actor, amount: -50, type: "hp", showScrolling: true});
        await game.xjzl.api.effects.addEffect(args.target, "prone");
        ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #e74c3c; background: rgba(231, 76, 60, 0.1);"><b><i class="fas fa-car-crash"></i> 猛烈撞击</b><br>${args.target.name} 撞上障碍，承受 50 流失并倒地！若撞到他人，请手动对其施加流失与倒地。</div></div>` });
    }
} else {
    const t1 = actor.token?.object || actor.getActiveTokens()[0];
    const t2 = args.target.token?.object || args.target.getActiveTokens()[0];
    if (t1 && t2) {
        const dist = Math.floor(canvas.grid.measurePath([t1.center, t2.center]).distance);
        const loss = dist * 5;
        await args.target.applyHealing({ healer: actor, amount: -loss, type: "mp", showScrolling: true});
        ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #3498db; background: rgba(52, 152, 219, 0.1);"><b><i class="fas fa-water"></i> 重溟卷流</b><br>距离 ${dist} 米，造成 ${loss} 点内力流失！</div></div>` });
    } else {
        ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #f39c12; background: rgba(243, 156, 18, 0.1);"><b><i class="fas fa-exclamation-triangle"></i> 距离计算失败</b><br>无法获取 Token 位置计算距离，请手动计算并流失内力。</div></div>` });
    }
}

// --- 云垂海立 连携特效 ---
const waitBleed = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_wait_bleed");
if (waitBleed) {
    const lvl = waitBleed.getFlag("xjzl-system", "stacks") || 1;
    const dmg = 5 + (lvl - 1) * 5;
    await args.target.applyHealing({ healer: actor, amount: -dmg, type: "hp", showScrolling: true});
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #8e44ad; background: rgba(142, 68, 173, 0.1);"><b><i class="fas fa-tint"></i> 云垂追击(穹苍)</b><br>附加 ${dmg} 点气血流失！</div></div>` });
}
const waitHeal = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_wait_heal");
if (waitHeal) {
    const lvl = waitHeal.getFlag("xjzl-system", "stacks") || 1;
    const heal = 5 + (lvl - 1) * 5;
    await actor.applyHealing({ healer: actor, amount: heal, type: "mp", showScrolling: true});
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #2ecc71; background: rgba(46, 204, 113, 0.1);"><b><i class="fas fa-plus"></i> 云垂追击(重溟)</b><br>自身回复 ${heal} 点内力！</div></div>` });
}

await game.xjzl.api.effects.removeEffect(actor, "wuxue_qiongming_wait_bleed", 99);
await game.xjzl.api.effects.removeEffect(actor, "wuxue_qiongming_wait_heal", 99);
await game.xjzl.api.effects.removeEffect(actor, "wuxue_qiongming_switched", 1);

if (!args.isHit) return;
const hasSky = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_sky");

if (hasSky) {
    if (args.isDying) {
        ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #e74c3c; background: rgba(231, 76, 60, 0.1);"><b><i class="fas fa-skull"></i> 穹苍狂舞</b><br>将 ${args.target.name} 打入濒死！你可以立即<b>不消耗动作</b>施展一次【扶摇万里】。</div></div>` });
    }
} else {
    await args.target.applyHealing({ healer: actor, amount: -20, type: "mp", showScrolling: true});
}

// --- 云垂海立 连携特效 ---
const waitBleed = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_wait_bleed");
if (waitBleed) {
    const lvl = waitBleed.getFlag("xjzl-system", "stacks") || 1;
    const dmg = 5 + (lvl - 1) * 5;
    await args.target.applyHealing({ healer: actor, amount: -dmg, type: "hp", showScrolling: true});
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #8e44ad; background: rgba(142, 68, 173, 0.1);"><b><i class="fas fa-tint"></i> 云垂追击(穹苍)</b><br>附加 ${dmg} 点气血流失！</div></div>` });
}
const waitHeal = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_wait_heal");
if (waitHeal) {
    const lvl = waitHeal.getFlag("xjzl-system", "stacks") || 1;
    const heal = 5 + (lvl - 1) * 5;
    await actor.applyHealing({ healer: actor, amount: heal, type: "mp", showScrolling: true});
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #2ecc71; background: rgba(46, 204, 113, 0.1);"><b><i class="fas fa-plus"></i> 云垂追击(重溟)</b><br>自身回复 ${heal} 点内力！</div></div>` });
}

const hasOcean = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_ocean");
if (hasOcean && args.hitCount > 0) {
    const totalHeal = args.hitCount * 20;
    await actor.applyHealing({ healer: actor, amount: totalHeal, type: "mp", showScrolling: true});
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #3498db; background: rgba(52, 152, 219, 0.1);"><b><i class="fas fa-water"></i> 重溟汲取</b><br>共命中 ${args.hitCount} 人，回复了 ${totalHeal} 点内力。若内力溢出，请手动等额转化为气血。</div></div>` });
}
await game.xjzl.api.effects.removeEffect(actor, "wuxue_qiongming_wait_bleed", 99);
await game.xjzl.api.effects.removeEffect(actor, "wuxue_qiongming_wait_heal", 99);
await game.xjzl.api.effects.removeEffect(actor, "wuxue_qiongming_switched", 1);

if (!args.isHit) return;
const hasSky = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_sky");

if (hasSky) {
    await args.target.applyHealing({ healer: actor, amount: -20, type: "hp", showScrolling: true});
} else {
    await actor.applyHealing({ healer: actor, amount: 10, type: "hp", showScrolling: true});
    await actor.applyHealing({ healer: actor, amount: 10, type: "mp", showScrolling: true});
}

// --- 云垂海立 连携特效 ---
const waitBleed = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_wait_bleed");
if (waitBleed) {
    const lvl = waitBleed.getFlag("xjzl-system", "stacks") || 1;
    const dmg = 5 + (lvl - 1) * 5;
    await args.target.applyHealing({ healer: actor, amount: -dmg, type: "hp", showScrolling: true});
}
const waitHeal = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_wait_heal");
if (waitHeal) {
    const lvl = waitHeal.getFlag("xjzl-system", "stacks") || 1;
    const heal = 5 + (lvl - 1) * 5;
    await actor.applyHealing({ healer: actor, amount: heal, type: "mp", showScrolling: true});
}

const hasOcean = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_ocean");
let msg = "";
if (hasOcean) {
    msg = `<b><i class="fas fa-water"></i> 重溟反击</b><br>命中 ${args.hitCount} 人，共回复 ${args.hitCount*10} 点气血内力。请手动移除 <b>2</b> 个负面状态。`;
} else {
    msg = `<b><i class="fas fa-cloud"></i> 穹苍反击</b><br>对目标造成了 20 气血流失。请手动移除 <b>2</b> 个负面状态。`;
}
ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #34495e; background: rgba(52, 73, 94, 0.1);">${msg}</div></div>` });

await game.xjzl.api.effects.removeEffect(actor, "wuxue_qiongming_wait_bleed", 99);
await game.xjzl.api.effects.removeEffect(actor, "wuxue_qiongming_wait_heal", 99);
await game.xjzl.api.effects.removeEffect(actor, "wuxue_qiongming_switched", 1);

const currentMp = actor.system.resources.mp.value;
const switched = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_switched");
const hasSky = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_sky");

if (args.costConfig.isDesperate && switched && hasSky) {
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #e74c3c; background: rgba(231, 76, 60, 0.1);"><b><i class="fas fa-exclamation-triangle"></i> 规则警告</b><br>若您刚才从重溟切至穹苍，剑气过盛，此招不可用于施展濒死一击！请自觉中止。</div></div>` });
}

args.costConfig.qiongmingCost = currentMp;

const cost = actor.system.resources.mp.value;
await actor.update({"system.resources.mp.value": 0});
args.flags.damageResult.qiongmingCost = cost;

if (!args.isHit) return;
const hasSky = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_sky");
const cost = args.damageResult.qiongmingCost || 0;
const val = Math.floor(cost / 2);

if (hasSky && val > 0) {
    await args.target.applyHealing({ healer: actor, amount: -val, type: "hp", showScrolling: true});
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #e74c3c; background: rgba(231, 76, 60, 0.1);"><b><i class="fas fa-wind"></i> 剑气轰入</b><br>${args.target.name} 承受 ${val} 气血流失！</div></div>` });
}

// --- 云垂海立 连携特效 ---
const waitBleed = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_wait_bleed");
if (waitBleed) {
    const lvl = waitBleed.getFlag("xjzl-system", "stacks") || 1;
    const dmg = 5 + (lvl - 1) * 5;
    await args.target.applyHealing({ healer: actor, amount: -dmg, type: "hp", showScrolling: true});
}
const waitHeal = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_wait_heal");
if (waitHeal) {
    const lvl = waitHeal.getFlag("xjzl-system", "stacks") || 1;
    const heal = 5 + (lvl - 1) * 5;
    await actor.applyHealing({ healer: actor, amount: heal, type: "mp", showScrolling: true});
}

const hasOcean = actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_qiongming_ocean");
if (hasOcean && args.hitCount > 0) {
    const cost = args.damageResult.qiongmingCost || 0;
    const val = Math.floor(cost / 2);
    if (val > 0) {
        await actor.applyHealing({ healer: actor, amount: val, type: "hp", showScrolling: true});
        ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="margin-left: 4px;"><div style="padding: 4px; border-left: 3px solid #2ecc71; background: rgba(46, 204, 113, 0.1);"><b><i class="fas fa-leaf"></i> 生生不息</b><br>回复了 ${val} 气血。</div></div>` });
    }
}
await game.xjzl.api.effects.removeEffect(actor, "wuxue_qiongming_wait_bleed", 99);
await game.xjzl.api.effects.removeEffect(actor, "wuxue_qiongming_wait_heal", 99);
await game.xjzl.api.effects.removeEffect(actor, "wuxue_qiongming_switched", 1);

// 性能优化：直接访问 itemTypes.armor (预索引数组)
const jade = actor.itemTypes.armor.find(i => i.name === "玄铁玉石" && i.system.equipped);

if (jade) {
    // 计算成长加值：(等级-1) * 10
    // 基础的20点由饰品自带，这里只负责加升级的部分
    const lvl = Math.max(1, args.move.computedLevel || 1);
    const bonus = (lvl - 1) * 10;

    if (bonus > 0) {
        // 直接修改内存属性
        system.resources.mp.bonus = (system.resources.mp.bonus || 0) + bonus;
    }
}

if (args.move.weaponType === "sword") {
    const lvl = Math.max(1, args.move.computedLevel || 1);
    const hitBonus = 5 + (lvl - 1) * 5;
    const critBonus = 1 + (lvl - 1) * 1;
    args.flags.bonusHit += hitBonus;
    args.flags.critThresholdMod += critBonus;
}

if (args.isHit) {
    const hasUnstable = args.target.effects.some(e => e.getFlag("xjzl-system", "slug") === "unstable");
    if (hasUnstable) {
        // 借助底层管理器的叠加机制，再次施加1回合的系统通用状态，系统会自动将原有回合数+1
        await game.xjzl.api.effects.addEffect(args.target, { id: "unstable", duration: { rounds: 1 } });
        actor.showFloatyText("下盘不稳延长!", { fill: "#FFA500" });
    }
}

const unstable = args.target.effects.some(e => e.getFlag("xjzl-system", "slug") === "unstable");
if (unstable) {
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: { title: "浑水摸鱼" },
        content: "<p>目标处于[下盘不稳]状态。你是否是使用【反应动作】释放此招？</p>",
        yes: { label: "是 (虚招+1)" },
        no: { label: "否" }
    });
    if (confirm) {
        args.flags.grantFeint += 1;
    }
}

if (!Macros.checkStance(actor, args)) return;
await game.xjzl.api.effects.addEffect(args.attacker, { id: "unstable", duration: { rounds: 1 } });
actor.showFloatyText("下盘不稳！", { fill: "#FFA500" });

const unstable = args.target.effects.find(e => e.getFlag("xjzl-system", "slug") === "unstable");
if (unstable) {
    await unstable.delete();
    const dongdaoAE = thisItem.effects.getName("东倒西歪");
    if (dongdaoAE) {
        const eff = dongdaoAE.toObject();
        delete eff._id;
        eff.origin = thisItem.uuid;
        eff.duration = { rounds: 3 };
        await game.xjzl.api.effects.addEffect(args.target, eff);
        ui.notifications.info(`${args.target.name} 陷入 [东倒西歪]`);
    }
}

if (actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "in_water")) {
    args.output.feint += 2;
    args.output.feintBonusDesc.push("水中作战: 虚招值 +2");
}

if (args.isBroken) {
    const nishuiAE = thisItem.effects.getName("溺水");
    if (nishuiAE) {
        const eff = nishuiAE.toObject();
        delete eff._id;
        eff.origin = thisItem.uuid;

        const lvl = Math.max(1, move.computedLevel || 1);
        eff.duration = { rounds: 1 + (lvl - 1) };

        await game.xjzl.api.effects.addEffect(args.target, eff);

        const msg = `<div class="xjzl-chat-card"><div style="padding:5px; font-weight:bold; color:#2c3e50;"><i class="fas fa-water"></i> 目标陷入溺水！(移动速度-5，缚身效果请手动处理)</div></div>`;
        ChatMessage.create({ content: msg, speaker: ChatMessage.getSpeaker({ actor: actor }) });
    }
}

if (args.isHit) {
    const lvl = Math.max(1, move.computedLevel || 1);
    const stacksToAdd = 1 + (lvl - 1);
    await game.xjzl.api.effects.addEffect(args.target, "benzhuo", stacksToAdd);
    ui.notifications.info(`已施加 ${stacksToAdd} 层笨拙！拉扯及禁足请手动处理。`);
}

if (actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "in_water")) {
    const lvl = Math.max(1, args.move.computedLevel || 1);
    S.combat.block += 5 + (lvl - 1) * 5;
    S.combat.kanpo += 1 + (lvl - 1) * 1;
}

// 1. 闭气成长计算 (常驻)
const lvl = Math.max(1, args.move.computedLevel || 1);
S.skills.biqi.mod += 2 + (lvl - 1) * 2;

// 2. 检测水中作战状态 (统一水域标记)
if (actor.effects.some(e => e.getFlag('xjzl-system', 'slug') === 'in_water')) {
    // 虚招对抗成长
    const feintBonus = 1 + (lvl - 1) * 1;
    S.combat.xuzhao += feintBonus;
    S.combat.kanpo += feintBonus;
}
